composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TOOLJET_HOST: {{env.TOOLJET_HOST}}
      SECRET_KEY_BASE: {{env.SECRET_KEY_BASE}}
      PG_HOST: {{serviceName}}-db
      PG_DB: {{env.PG_DB}}
      PG_USER: {{env.PG_USER}}
      PG_PASS: {{env.PG_PASS}}
      TZ: {{env.TZ}}
    depends_on:
      - {{serviceName}}-db
  {{serviceName}}-db:
    image: postgres:13-alpine
    container_name: {{serviceName}}-db
    restart: unless-stopped
    environment:
      POSTGRES_DB: {{env.PG_DB}}
      POSTGRES_USER: {{env.PG_USER}}
      POSTGRES_PASSWORD: {{env.PG_PASS}}
    volumes:
      - {{appDataPath}}/db:/var/lib/postgresql/data
